const r = await tools.exec_command({cmd:"python - <<'PY'
import json, numpy as np
x=json.load(open('data/calibration.json'))

def pred(e,mu):
 k=e['mode']*np.pi/e['length']; w=e['frequency_ratio']*k; d=e['drive']
 V=d/(mu*k*k+1j*(k*k/w-w)); R=-1j*k*V/w
 return abs(R)
for mu in [0.08,.1,.12,.13,.14,.15,.16,.18]:
 y=np.array([r['value'] for r in x]); p=np.array([pred(r['input'],mu) for r in x]);
 print(mu,np.sqrt(np.mean(((p-y)/.0002)**2)),np.mean(p-y))
# optimize golden section
lo,hi=.08,.18
def loss(mu):return sum((pred(r['input'],mu)-r['value'])**2 for r in x)
for _ in range(100):
 a=lo+(hi-lo)/3;b=hi-(hi-lo)/3
 if loss(a)<loss(b):hi=b
 else:lo=a
mu=(lo+hi)/2
print('best',mu,loss(mu),np.sqrt(loss(mu)/len(x))/.0002)
PY","workdir":"/app","yield_time_ms":10000,"max_output_tokens":10000});
text(r.output);

